from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Treat the top and bottom grid edges as exterior; fill background pockets
    # separated from both by the colored lines.
    seen = set()
    q = deque()
    for r in (0, h - 1):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in seen:
                seen.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background and (r, c) not in seen:
                out[r][c] = 4
    return out

